#include <bits/stdc++.h>
using namespace std;

vector<int> topKFrequent(vector<int>& nums, int k) {
    unordered_map<int, int> counts;
    for (int num : nums) counts[num]++;
    vector<int> values;
    for (auto& entry : counts) values.push_back(entry.first);
    sort(values.begin(), values.end(), [&](int a, int b) {
        return counts[a] > counts[b];                                        // sorts every distinct value
    });
    return vector<int>(values.begin(), values.begin() + k);
}

int main() {
    vector<int> nums = {1, 1, 1, 2, 2, 3};
    vector<int> result = topKFrequent(nums, 2);
    for (int v : result) cout << v << " ";
    cout << endl;
    return 0;
}

