import java.util.*;

public class Main {
    int[] topKFrequent(int[] nums, int k) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (int num : nums) counts.put(num, counts.getOrDefault(num, 0) + 1);
        List<List<Integer>> buckets = new ArrayList<>();
        for (int i = 0; i <= nums.length; i++) buckets.add(new ArrayList<>());    // one bucket per possible frequency
        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            buckets.get(entry.getValue()).add(entry.getKey());
        }
        int[] result = new int[k];
        int idx = 0;
        for (int freq = buckets.size() - 1; freq > 0 && idx < k; freq--) {
            for (int value : buckets.get(freq)) {
                result[idx++] = value;
                if (idx == k) break;
            }
        }
        return result;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(Arrays.toString(solution.topKFrequent(new int[]{1, 1, 1, 2, 2, 3}, 2)));
    }
}

